def countOrderedSums(nums, target):
    MOD = 1_000_000_007
    ways = [0] * (target + 1)
    ways[0] = 1
    for t in range(1, target + 1):
        total = 0
        for x in nums:
            if x <= t:
                total += ways[t - x]
        ways[t] = total % MOD
    return ways[target]
